<h1>Configuração inicial</h1>
<p class="muted">Crie o primeiro usuário. Ele receberá o perfil Desenvolvedor.</p><?php if (!empty($error)): ?><p class="error"><?= e($error) ?></p><?php endif; ?><form method="post"><input type="hidden" name="_csrf" value="<?= e($csrf) ?>"><label>Nome da aplicação <input name="app_name" value="PHP Admin Framework" required></label><label>Nome do usuário <input name="name" required></label><label>Login <input name="username" pattern="[a-zA-Z0-9._-]{3,30}" placeholder="Ex: admin, j.silva" title="O login deve conter entre 3 e 30 caracteres (letras, números, '.', '_' ou '-'), sem @" required></label><label>Senha <input type="password" name="password" minlength="8" required></label><label>Confirmação <input type="password" name="password_confirmation" minlength="8" required></label><?php if ($app->config->get('app_setup_key')): ?><label>Chave de setup <input type="password" name="setup_key" required></label><?php endif; ?><button type="submit">Instalar</button></form>